/* @autogenerated */
package net.civeira.phylax.features.oauth.client.application.usecase.updatedynamicclient;

import java.util.LinkedHashSet;
import java.util.Set;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.oauth.client.application.usecase.registerclient.RegisterClientUsecase;
import net.civeira.phylax.features.oauth.client.domain.DcrMetadataPolicy;
import net.civeira.phylax.features.oauth.client.domain.DcrRegistrationRules;
import net.civeira.phylax.features.oauth.client.domain.DynamicClientData;
import net.civeira.phylax.features.oauth.client.domain.DynamicClientRequest;
import net.civeira.phylax.features.oauth.client.domain.exception.DynamicClientException;
import net.civeira.phylax.features.oauth.client.domain.gateway.DynamicClientGateway;

/**
 * Replaces the metadata of a dynamically registered client (RFC 7592 §2.2, task 2.1).
 *
 * <p>
 * Same validation as the registration, against the current tenant rules. The grants the client
 * already had may stay even if the tenant no longer lists them (they may have come from its initial
 * access token), except password when the tenant no longer allows it.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class UpdateDynamicClientUsecase {

  private final DynamicClientGateway gateway;

  /**
   * Updates a client.
   *
   * @param tenant tenant name of the endpoint
   * @param issuer issuer of the tenant
   * @param clientId client identifier
   * @param registrationAccessToken token presented in clear
   * @param request new metadata
   * @return the stored metadata
   * @throws DynamicClientException invalid_token, invalid_client_metadata or invalid_redirect_uri
   */
  public DynamicClientData update(String tenant, String issuer, String clientId,
      String registrationAccessToken, DynamicClientRequest request) {
    DynamicClientData current = gateway.find(tenant, clientId, registrationAccessToken)
        .orElseThrow(DynamicClientException::invalidRegistrationToken);
    DcrRegistrationRules rules = gateway.readRegistrationRules(tenant);
    if (!rules.enabled()) {
      throw DynamicClientException.registrationNotAllowed();
    }
    Set<String> grants = new LinkedHashSet<>(rules.grantTypes());
    grants.addAll(current.getGrantTypes());
    DynamicClientRequest metadata =
        DcrMetadataPolicy.validate(request, rules.withGrantTypes(grants));
    if (!metadata.getTokenEndpointAuthMethod().equals(current.getTokenEndpointAuthMethod())) {
      // Switching between public and confidential would need a new secret: register again.
      throw DynamicClientException
          .invalidClientMetadata("token_endpoint_auth_method cannot change");
    }
    return gateway.update(tenant, clientId, registrationAccessToken, metadata)
        .map(
            data -> data.toBuilder()
                .registrationClientUri(
                    RegisterClientUsecase.registrationClientUri(issuer, clientId))
                .build())
        .orElseThrow(DynamicClientException::invalidRegistrationToken);
  }
}
